"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["3806"],{63986(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.inscricao.nome_social_ausente_na_conta","status":422,"titulo":"A conta do candidato n\xe3o tem nome social cadastrado"},"descricao":{"codigo":"uniplus.selecao.inscricao.nome_social_ausente_na_conta","requisitos":["UNI-REQ-0153","UNI-REQ-0144"],"oQueAconteceu":["Como a regra \xe9 do nome social (UNI-REQ-0153), e n\xe3o do formul\xe1rio, esta recusa\\ntamb\xe9m vale, com o mesmo c\xf3digo, no envio do formul\xe1rio que coleta a escolha do\\nuso do nome social em processo de resultado importado, que n\xe3o tem inscri\xe7\xe3o.\\nNesse caso, onde o texto diz \\"inscri\xe7\xe3o\\", leia \\"o formul\xe1rio da fase\\". Isso \xe9 regra\\nprevista, ainda n\xe3o emitida pela API fora da inscri\xe7\xe3o.","O candidato marcou que deseja usar nome social, mas a conta dele n\xe3o tem\\nnome social cadastrado. O nome social \xe9 dado da conta, e n\xe3o de cada\\ninscri\xe7\xe3o: a inscri\xe7\xe3o usa o nome social que est\xe1 na conta e n\xe3o o aceita\\ndigitado. Sem nome social na conta, n\xe3o h\xe1 nome social para a inscri\xe7\xe3o\\nusar.","A grava\xe7\xe3o do rascunho com a escolha de usar e o campo vazio \xe9 aceita, para\\nque o candidato possa salvar a inscri\xe7\xe3o antes de cadastrar o nome social.\\nA recusa sai no envio, ou na grava\xe7\xe3o do rascunho quando o corpo traz um\\nnome social que a conta n\xe3o tem."],"comoResolver":["Cadastre o nome social em **Meu perfil**, no menu da conta, e volte para\\nconcluir a inscri\xe7\xe3o: o campo passa a mostrar o nome social da conta. Quem\\nn\xe3o quer usar nome social nesta inscri\xe7\xe3o desmarca a op\xe7\xe3o e envia de novo."],"ondeAparece":["Envio da inscri\xe7\xe3o do candidato","Grava\xe7\xe3o do rascunho da inscri\xe7\xe3o, quando o corpo traz um nome social","Envio do formul\xe1rio que coleta a escolha do uso do nome social, em processo de resultado importado (regra prevista, UNI-REQ-0144)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Inscricao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);